export const liuRenShenShaInfo: { [key: string]: [string, string, string, string] } = {
	'大安': ['大安', '大吉', '木', '事事昌,心安、吉祥，就近不可远，求稳不激进为最佳'],
	'留连': ['留连', '小凶', '水', '有难度受阻碍，情况暗昧不明，事情反复纠缠，拖延，漫长'],
	'速喜': ['速喜', '中吉', '火', '非常快的顺利、开心和满意'],
	'赤口': ['赤口', '中凶', '金', '或有不吉、惊恐、凶险或口舌是非'],
	'小吉': ['小吉', '小吉', '木', '吉利、顺利、舒服开心'],
	'空亡': ['空亡', '大凶', '土', '不抱希望，感觉会落空，无盼头']
};

export const getLiuRenShenShaInfo = (item: string): [string, string, string, string] | [] => {
	const info = liuRenShenShaInfo[item];
	return info ? info : [];
};


/*
遇事即刻起卦，无事勿占，凡事只占一次，再占不验。
凡一切途径得数，除以12，去余数作时辰，月日即用历书所载为准。

六壬时课有神通，大安留连速喜中，　　赤口小吉空亡记，吉凶祸福细推祥。
  病占大安不用慌，上天佑你保健康；　　病占留连多忧愁，绵绵缠缠病不离；
  病占速喜病来急，急速医治别务期；　　病占赤口是重衰，忍受痛苦度病关；
  病占小吉为吉利，不用慌忙病有安；　　病占空亡为无病，有病可能是癔病。
 
  官司大安是不顺，要找贵人来疏通；　　官司留连有拖延，耐心等待不要忙；
   官司速喜有明理，是黑是白自分明；　　官司小吉要答礼，舍财保身得平安；
   官司赤口是不顺，官司输定必不疑      官司空亡无灾难，虚惊一场不要慌。
 
  财占大安不动财，动则钱财有损伤；　　财占留连为无财，真想求财去远方；
  财占速喜九分财，若要得全贵人帮；　　财占赤口一口财，辛辛苦苦才赚到；
  财占小吉流动财，即有去的也有来；　　财占空亡意外财，要逢天时好运帮。
 
  大安外出不宜远，不求财来可以走；　　留连外出是远行，忧心忡忡有拖延；
  速喜外出走的慌，匆匆忙忙来观光；　　赤口外出有凶险，按兵不动是真招；
  小吉外出最顺当，一路观光一路欢；　　空亡外出最不欢，有矢无中不乐观。
 
 
  婚占大安婚自安，青梅竹马结良缘；　　婚占留连有犹豫，男女两家都不欢；
  婚占速喜喜喜喜，一见钟情成一家；　　婚占赤口婚不吉，棒打鸳鸯各一方；
  婚占小吉桃花婚，男的潇洒女风光；　　婚占空亡喜无音，单身男女泪汪汪。
*/

