//得到某一个六壬的第一阶段 结果 
export const getLiuRenCategreyFirstResult = (item: string, liuRenShenShaName: string): string => {
	const categoryList = getLiuRenCategreyFirst(item);
	const idx = liuRenShenSha.indexOf(liuRenShenShaName);

	// console.log(categoryList,idx,liuRenShenShaName,item)
	return categoryList[idx] ?? '';
}

//得到某一个六壬的第一阶段 结果 
export const getLiuRenCategreySecondResult = (item: string, liuRenShenShaName: string): string => {
	const categoryList = getLiuRenCategreySecond(item);
	const idx = liuRenShenSha.indexOf(liuRenShenShaName);

	// console.log(categoryList,idx,liuRenShenShaName,item)
	return categoryList[idx] ?? '';
}

//得到某一个六壬的结果 
export const getLiuRenCategreyResult = (item: string, liuRenShenShaName: string): string => {
	const categoryList = getLiuRenCategrey(item);
	const idx = liuRenShenSha.indexOf(liuRenShenShaName);

	// console.log(categoryList,idx,liuRenShenShaName,item)
	return categoryList[idx] ?? '';
}

