// 12串宫法
// https://www.sohu.com/a/455636853_121043484#:~:text=%E4%BB%8A%E5%A4%A9%E8%BF%99%E9%87%8C%E5%B0%B1%E9%80%9A%E8%BF%87%E8%AF%A6%E7%BB%86%E7%9A%84
// 相通字就是，甲通寅，乙通卯，丙通巳，丁通午，戊通戌，己通丑，庚通申，辛通酉，壬通亥，癸通子。
// 12神分别是：太岁（1），青龙（2），丧门（3），六合（4），官符（5），小耗（6），大耗（7），朱雀（8），白虎（9），贵神（10），吊客（11），病符（12）。
// 其次，我们就找到相通字，己通丑，那么丑就是太岁。根据12地支那么去排。丑后面是寅（按子丑寅卯辰巳午未申酉戌亥的顺序去排），
// 12神的顺序是太岁后面是青龙（按太岁，青龙，丧门，六合，官符，小耗，大耗，朱雀，白虎，贵神，吊客，病符的顺序去排），所以
// 寅为青龙，寅通甲，所以甲也是青龙。那么接下来就是
// 卯就是丧门，那么卯通乙，乙也是丧门。

// 根据12神得到地支禄是什么 
export const shenSha12GanToZhi = (item: string): string => {
	// 相通字就是，甲通寅，乙通卯，丙通巳，丁通午，戊通戌，己通丑，庚通申，辛通酉，壬通亥，癸通子。
	// 和禄神 戊通戌，己通丑 两个是不同的 
	const DataMap: { [key: string]: string } = {
		"甲": '寅',
		"乙": '卯',
		"丙": '巳',
		"丁": '午',
		"戊": '戌',
		"己": '丑',
		"庚": '申',
		"辛": '酉',
		"壬": '亥',
		"癸": '子',
	};
	return DataMap[item];
};



// 八字中没有的字，往往是最至关重要的字，
//  盲派中的伏神也就是冲出，拱出，合化出来之物。
//  暗藏的东西，伏财的命局就是真财不外露，得财对男命为金屋藏娇，伏多少有多少，
//  伏官的命局就是有多少官职，女命就是有多少个情郎。
//  食伤，比劫，印星同样道理。注意：岁运露出之时，就是失去之时。
// 
// 飞神法则：
// 天干合飞：二甲无己飞出己、二己无甲飞甲、二庚无乙飞出乙，二乙无庚飞出庚、二丙无辛飞出辛，二辛无丙飞出丙、二丁无壬飞出壬、二壬无丁飞出丁、二戊无癸飞出癸、二癸无戊飞出戊。
// 地支合飞：二丑无子飞出子、二寅无亥飞出亥、二亥无寅飞出寅、二戌无卯飞出卯、二辰无酉飞出酉、二巳无申飞出申、二申无巳飞出巳、二未无午飞出午。
// 地支冲飞：二子无午飞出午、二午无子飞出子、二寅无申飞出申、二申无寅飞出寅、二卯无酉飞出酉、二酉无卯飞出卯、二巳无亥飞出亥、二亥无巳飞出巳。

// 地支拱飞：巳丑无酉飞出酉、申辰无子飞出子、寅戌无午飞出午、亥未无卯飞出卯、寅辰无卯飞出卯、巳未无午飞出午、申戌无酉飞出酉、亥丑无子飞出子。

// 传递出来的数组,一般是八字的数组或身宫命的数组 strArr= []     strKong =[]  空亡的数组  以日支  

export const getMangPaiFeiShen = (strArr: string[], strKong: string[], elsList: string[]): string[] => {
	const FeiElsArr = []

	const counts = countArrayElements(strArr);

	const pairMap1 = new Map([
		['甲', '己'],
		['己', '甲'],
		['庚', '乙'],
		['乙', '庚'],
		['丙', '辛'],
		['辛', '丙'],
		['丁', '壬'],
		['壬', '丁'],
		['戊', '癸'],
		['癸', '戊'],
		['子', '午'],
		['丑', '子'],
		['寅', '亥'],
		['卯', '酉'],
		['辰', '酉'],
		['巳', '申'],
		['午', '子'],
		['未', '午'],
		['申', '巳'],
		['酉', '卯'],
		['戌', '卯'],
		['亥', '寅'],
	]);
	const pairMap2 = new Map([
		['寅', '申'],
		['巳', '亥'],
		['申', '寅'],
		['亥', '巳'],
	]);


	for (const [key, value] of counts) {

		if (!elsList.includes(key)) {
			continue;
		}


		if (value >= 2) {

			if (!strArr.includes(pairMap1.get(key))) {
				if (pairMap1.get(key) || ''.length > 0 && !FeiElsArr.includes(pairMap1.get(key))) {
					//  空亡的不能飞出来东西
					if (!strKong.includes(key)) {
						FeiElsArr.push(pairMap1.get(key));
					}

				}

			}

			if (!strArr.includes(pairMap2.get(key))) {
				if (pairMap2.get(key) || ''.length > 0 && !FeiElsArr.includes(pairMap2.get(key))) {
					//  空亡的不能飞出来东西
					if (!strKong.includes(key)) {
						FeiElsArr.push(pairMap2.get(key));
					}
				}

			}
		}


		// 地支拱飞：巳丑无酉飞出酉、申辰无子飞出子、寅戌无午飞出午、   亥未无卯飞出卯、   寅辰无卯飞出卯、巳未无午飞出午、申戌无酉飞出酉、亥丑无子飞出子。

		if ((key === '巳' || key === '丑') && ((counts.get('丑') || 0) > 0 && (counts.get('巳') || 0) > 0) && !strArr.includes('酉')) {
			if (!FeiElsArr.includes('酉') && !strKong.includes('巳') && !strKong.includes('丑')) {
				FeiElsArr.push('酉');
			}
		}

		if ((key === '申' || key === '辰') && ((counts.get('申') || 0) > 0 && (counts.get('辰') || 0) > 0) && !strArr.includes('子')) {
			if (!FeiElsArr.includes('子') && !strKong.includes('申') && !strKong.includes('辰')) {
				FeiElsArr.push('子');
			}
		}

		if ((key === '寅' || key === '戌') && ((counts.get('寅') || 0) > 0 && (counts.get('戌') || 0) > 0) && !strArr.includes('午')) {
			if (!FeiElsArr.includes('午') && !strKong.includes('寅') && !strKong.includes('戌')) {
				FeiElsArr.push('午');
			}
		}



		if ((key === '亥' || key === '未') && ((counts.get('亥') || 0) > 0 && (counts.get('未') || 0) > 0) && !strArr.includes('卯')) {
			if (!FeiElsArr.includes('卯') && !strKong.includes('亥') && !strKong.includes('未')) {
				FeiElsArr.push('卯');
			}
		}



		// 地支拱飞： 寅辰无卯飞出卯、巳未无午飞出午、申戌无酉飞出酉、亥丑无子飞出子。
		if ((key === '寅' || key === '辰') && ((counts.get('寅') || 0) > 0 && (counts.get('辰') || 0) > 0) && !strArr.includes('卯')) {
			if (!FeiElsArr.includes('卯') && !strKong.includes('寅') && !strKong.includes('辰')) {
				FeiElsArr.push('卯');
			}
		}
		if ((key === '巳' || key === '未') && ((counts.get('巳') || 0) > 0 && (counts.get('未') || 0) > 0) && !strArr.includes('午')) {
			if (!FeiElsArr.includes('午') && !strKong.includes('巳') && !strKong.includes('未')) {
				FeiElsArr.push('午');
			}
		}
		if ((key === '申' || key === '戌') && ((counts.get('申') || 0) > 0 && (counts.get('戌') || 0) > 0) && !strArr.includes('酉')) {
			if (!FeiElsArr.includes('酉') && !strKong.includes('申') && !strKong.includes('戌')) {
				FeiElsArr.push('酉');
			}
		}

		if ((key === '亥' || key === '丑') && ((counts.get('亥') || 0) > 0 && (counts.get('丑') || 0) > 0) && !strArr.includes('子')) {
			if (!FeiElsArr.includes('子') && !strKong.includes('亥') && !strKong.includes('丑')) {
				FeiElsArr.push('子');
			}
		}
	}

	return FeiElsArr
}

// 通过盲派飞神得到包含什么信息 

export const getSomethingByMangPaiFeiShen = (feishenElsArray: string[], taisui: string, daygan: string, sex: number): string[] => {

	let DataMap: string[] = []

	for (const els of feishenElsArray) {
		// 得到十神 
		let shishen = getShiShenByGanOrZhi(daygan, els)[0]
		// 得十串宫十神 
		let shensha12 = get12ShenSha(taisui, els)
		// 有桃花
		if (['子', '午', '卯', '酉'].includes(els)) {
			let char = '会有异性缘好,有偏桃花'
			if (!DataMap.includes(char)) {
				DataMap.push(char)
			}
		}
		// 有驿马
		if (['寅', '申', '巳', '亥'].includes(els)) {
			let char = '工作地点变化多,走动奔波多或出差多。'
			if (!DataMap.includes(char)) {
				DataMap.push(char)
			}
		}
		// 有文昌星  
		if (getWenChang(daygan) === els || shensha12 === '青龙') {
			let char = '会继续学习拿到后天的学历文凭证书荣誉。'
			if (!DataMap.includes(char)) {
				DataMap.push(char)
			}
		}
		// 大小耗
		if (shensha12 === '大耗' || shensha12 === '大耗') {
			let char = '会常破财，耗财。'
			if (!DataMap.includes(char)) {
				DataMap.push(char)
			}
		}

		if (shensha12 === '丧门' || shensha12 === '吊客') {
			let char = '12神是' + shensha12 + ',如有' + getLiuQinByShiShen(shishen)[sex] + '相处缘份少或身体不好或去世较早。'
			if (!DataMap.includes(char)) {
				DataMap.push(char)
			}
		}



		if (shensha12 === '朱雀') {
			let char = getLiuQinByShiShen(shishen)[sex] + '有是非口角纠缠官司的事情。'
			if (!DataMap.includes(char)) {
				DataMap.push(char)
			}
		}

		if (shensha12 === '六合') {
			let char = '财旺,有偏财，与人合作能赚到钱。'
			if (!DataMap.includes(char)) {
				DataMap.push(char)
			}
		}
		if (shensha12 === '太岁' || shensha12 === '官符') {
			let char = '工作上都会被人管压力大。'
			if (!DataMap.includes(char)) {
				DataMap.push(char)
			}
		}

		if (shensha12 === '白虎') {
			let char = `${(sex === 0 ? '生孩子会是剖腹产' : '')}自己注定有手术或血光意外。 `
			if (!DataMap.includes(char)) {
				DataMap.push(char)
			}
		}

		if (shensha12 === '贵神') {
			let char = '做事顺昌，总能得心应手遇到贵人。'
			if (!DataMap.includes(char)) {
				DataMap.push(char)
			}
		}

		if (shensha12 === '病符') {
			let char = getLiuQinByShiShen(shishen)[sex] + '身体不好，老人的话可能早去世。'
			if (!DataMap.includes(char)) {
				DataMap.push(char)
			}
		}
		if (shishen === '正财' || shishen === '偏财') {
			let char = '常说自己没钱，其实深藏不露,其实很有正偏财。'
			if (!DataMap.includes(char)) {
				DataMap.push(char)
			}
		}

		if (shishen === '食神' || shishen === '伤官') {
			let char = '会掌握技能创造除工作外的偏财源。'
			if (!DataMap.includes(char)) {
				DataMap.push(char)
			}
		}

		if (shishen === '正官') {
			let char = sex === 1 ? '容易当领导或管理团队。' : '会接手管理团队的事情。'
			if (!DataMap.includes(char)) {
				DataMap.push(char)
			}
		}
		if (shishen === '七杀') {
			let char = sex === 1 ? '当兵或执法人的狠劲。' : '自己会有情人或不能公开的相恋之人。'
			if (!DataMap.includes(char)) {
				DataMap.push(char)
			}
		}

		if (shishen === '比肩' || shishen === '劫财') {
			let char = '兄弟姐妹多或朋友哥们越来越多。'
			if (!DataMap.includes(char)) {
				DataMap.push(char)
			}
		}

		if (shishen === '正印' || shishen === '偏印') {
			let char = '开始学习新知识或继续攻关后天荣誉或更高学历。'
			if (!DataMap.includes(char)) {
				DataMap.push(char)
			}
		}


	}

	return DataMap;
};

// 根据金镖门的方法，得到命宫的元素是什么 
// 推算方法
// 1.记住月支对应的数:寅卯辰巳午未申酉成亥子丑十二月建，寅记一，卯记二，其它类推。
// 2.记住时支对应的数:寅卯辰巳午未申酉成亥子丑十二时辰，寅记一、卯记二，其它类推。
// 3.记住命宫数:寅卯辰巳午未申酉戍亥子丑十二命宫，寅记一，卯记二，其它类推。
// 4.推演命宫(与子平法不同)用12或 24减月时数之和即为命宫。如寅月寅时生人，应是12-(1+1)=10，10对应
// 到命宫是亥，即亥宫安命。如果月时数之和大于 12，前面就用 24。这 12和 24 是定数。
// 5.记住星宿对应的数和流年太岁:一太岁，太岁记一。其它类推。流年太岁是指当年的地支，如2020年，庚子年，子为太岁。
// 6.推算管年星宿:
// 由流年地支顺数到命宫即为管年星宿，如子数到亥为十二。十二是病符，命主今年为病符星管年，主发生不吉利的事情，有问题，有毛病的事情。

export const shenSha12GetMingGongEls = (MonthZhi: string, TimeZhi: string): string => {
	let MonthZhiIdx = shenSha12DizhiList.indexOf(MonthZhi) + 1
	let TimeZhiIdx = shenSha12DizhiList.indexOf(TimeZhi) + 1
	let pos = 0;
	let cnt = MonthZhiIdx + TimeZhiIdx
	if (cnt >= 12) {
		pos = 24 - cnt
	}
	else {
		pos = 12 - cnt
	}
	let mingEls = shenSha12DizhiList[pos - 1]

	return mingEls;
}

// 根据推算出来的命宫得出来十二神煞

export const shenSha12GetMingGongShenSha = (TaisuiEls: string, MonthZhi: string, TimeZhi: string): string => {

	let mingEls = shenSha12GetMingGongEls(MonthZhi, TimeZhi)
	let shensha = get12ShenSha(TaisuiEls, mingEls)
	return shensha;
}






