// 得到12神串宫  参数： 太岁的地支(可以是干也可以是支)  要得到结果的干支  

export const get12ShenSha = (TaisuiEls: string, Els: string): string => {
	let taisuiels = '', zhiEls = ''

	if (LunarUtil.GAN.includes(TaisuiEls)) {
		taisuiels = shenSha12GanToZhi(TaisuiEls)
	}
	else {
		taisuiels = TaisuiEls
	}

	if (LunarUtil.GAN.includes(Els)) {
		zhiEls = shenSha12GanToZhi(Els)
	}
	else {
		zhiEls = Els
	}

	let refData = ''
	let idxOftaiSui = dizhiList.indexOf(taisuiels)
	let idxOfEls = dizhiList.indexOf(zhiEls)
	let steps = 0
	if (idxOfEls >= idxOftaiSui) {
		steps = idxOfEls - idxOftaiSui
	}
	else {
		steps = (12 - idxOftaiSui) + idxOfEls
	}

	refData = shenSha12[steps]
	return refData

}
// 得到串宫颜色 

export const GetChuanGongColor = (str: string) => {
	const shuxing = get12ShenShaDesp(str)[0]
	const colorList: string[] = ['#009688', '#9E9E9E', '#ea2a6a', '#FF5722', '#a17323'];
	const shuxingList: string[] = ['吉星', '中性星', '小凶星', '大凶星']
	return colorList[shuxingList.indexOf(shuxing)];
}

export const GetChuanGongLevel = (str: string) => {
	const shuxing = get12ShenShaDesp(str)[0]
	const levelList: number[] = [10, 0, -10, -10];
	const shuxingList: string[] = ['吉星', '中性星', '小凶星', '大凶星']
	return levelList[shuxingList.indexOf(shuxing)];
}



// 得到十二神宫的说明
export const get12ShenShaDesp = (item: string) => {
	const DataMap: { [key: string]: string[] } = {
		"太岁": ['中性星', '太岁压运起祸端，伤财惹气心不甘。 惊天动地祸来临，是是非非把人缠。他人闲事切勿管，未雨绸缪且安然。太岁运年多忧愁，口舌临门不自由。疾病缠身小人侵，婚姻钱财莫强求。运逢太岁难行舟，劝君持重莫远游。', '太岁为中性星，遇吉星则吉，遇凶星则凶。无论见吉星还是凶星。只要太岁在地支即为凶。'],
		"青龙": ['吉星', '青龙是喜神，大喜有几重，荷花生贵子，门前应挂红。青龙入命大吉祥，创业谋事有人帮，添人进口生贵子，家中喜事一桩桩，官运亨通财运好，即使有祸不为殃。 ', '青龙是吉星，旺为吉，见吉星为吉。如果被凶星盖头则凶。被中性星盖头亦吉。'],
		"丧门": ['小凶星', '丧门是哭星，落泪有几行。丧门运年心不安，求财望喜多枉然， 不是伤人就损财，忧思重重整一年， 不有内孝有外孝，犯着丧门泪涟涟。', '丧门是小凶星，弱为吉。空亡为吉，如果被吉星盖头则应小凶。'],
		"六合": ['吉星', '六合见六合，必定喜事逢，有妻生贵子，无妻娶娇娥。 六合入命大吉昌，万事顺随人丁旺，多得亲友来辅助，纵有逆风不起浪，求财谋利皆如意，添喜进财时运强。', '六合为吉星。'],
		"官符": ['中性星', '官符为红鸾，有喜在当年， 少惹是非事，免祸在身边。官符入命令人忧，是非口舌无止休，平地也会起风波，忧思如麻不断头，财帛易散物易损，犯了官符难自由。', '官符为中性星，可吉可凶。'],
		"小耗": ['小凶星', '时运多颠倒，做事不牢靠, 金银多耗散，家财遭鬼盗。小耗之年多烦恼，是非口舌几多招， 官非易起气易惹，金银财钱易损耗， 东奔西跑无定处，办事不遂多阻挠。', '小耗为小凶星。'],
		"大耗": ['大凶星', '大耗定不祥，父母有人伤。  今年财要损，朋友来反目。  背运有人伤，落井会下石。 年逢岁破祸非轻，官司窃骗极易生， 不是破财遭凶事，就是体弱身染病， 若与白虎连一起，凶丧孝服灾更重。', '大耗为大凶星。'],
		"朱雀": ['大凶星', '朱雀压运凶，口舌是非多。 内外来磨磋，小人当前横。事事犯啰唆，有理无人理。 有冤无处诉，还要背黑锅。 朱雀入命口舌生，风波扰得心不宁，求名求财皆不利，凡事多磨事少成， 幸喜紫薇当头照，逢凶化吉保太平。', '朱雀为大凶星。'],
		"白虎": ['大凶星', '白虎当头坐，无灾也有祸。铁罗汉落井，有力难施展。白虎下山来，又遭口舌运，又遭凶灾气。白虎入命最凶险，血光伤疾度难关，更有内外孝服事，天灾横祸需防范，白虎之年心难安，一年四季不消闲。', '白虎为大凶星。不可被任何星盖头，盖头必凶。'],
		"贵神": ['吉星', '贵神压运事吉祥，财源广进喜又和，春不见喜秋也见，财喜双全不用说，男遇贵神天赐祥，女见贵神喜事多。贵神入命福寿长，财运亨通身安康，善与人交受人敬，高官厚禄名远扬，凡事都有贵人帮，运逢贵神心欢畅.', '贵神为吉星。'],
		"吊客": ['小凶星', '吊客压运事有凶，定有是非闹灾行，男犯吊客主不顺，女犯吊客有灾星。吊客流年也为凶，四方亲人不太平，求财谋利难如意，晦气会有几多重，岁逢吊客心不安，旧愁去了新愁添。', '吊客为小凶星。'],
		"病符": ['小凶星', '病符压运很难强，事要三思免祸殃，病魔缠身使人忧，三灾八难难得躲。病符入命恶重重，疾病缠身家不宁，办事处事心不顺，朝朝暮暮愁云生，凭你是个硬神汉，也得脱上皮几层。', '病符为小凶星。'],

	};
	return DataMap[item];

}

// 命官、身官。盲派认为胎元代表了命主本人的体质，命宫代表了命主本人的事业，身官则代表了命主本人的财运，
// 代表了命主本人一生的立身之本(健康、事业、财运)
// 五、一、十二神互变的规律:
// 1.太岁官符变朱雀，朱雀变贵神，贵神变丧吊，丧吊变官符;
// 2.青龙白虎互变，大小耗与六合互变;
// 3.病符变无病

// 太岁变朱雀    青龙变白虎     白虎变青龙   
// 六合变耗星    耗星变六合     朱雀变贵神    
// 贵神变丧吊    丧吊变官符     太岁
// 病符变无病    官符变朱雀

// 得到十二神宫的说明逢空亡的时候什么切换，切换表如下

// 食伤落白虎变青龙，食伤代表财源，白虎代表争斗打斗，青龙代表贵人代表喜庆，说明因为财与经济的方面而出现纠纷与人争斗打斗事件，最后得到贵人化解。
// 财星落吊客变官符，财为钱财，吊客代表纠纷纠缠忧愁烦恼，官符代表官方政府贵人，说明钱财方面出现经济纠纷，最后得到官方政符化解。

// 官星落官符变朱雀，官符官星代表工作事业，官星也代表女人的丈夫或其他男人，朱雀代表口舌纠纷官非小人，指会因工作事业而产生的纠纷官非小人阻路。
// 官星落六合变耗，官星代表工作事业，也代表女人的丈夫或男人，六合代表合作合伙，耗代表耗财破财投资失败。

// 官符配白虎，说明身体不是很好，出现问题，白虎落在何部位，则指哪部位可能有病。
// 吊客配太岁，说明事业先凶后吉，先期处于纠结波动状态，后期多得贵人助而有好转。
// 印星朱雀配白虎，说明此年会有因文件合同证书、或因工作单位、或房屋车辆等围绕着的一些事情，犯小人惹口舌是非，产生纠纷官司或会生气打斗纠缠、或是有血光之灾等。
// 朱雀配白虎，说明会出现经济纠纷与官司之事。

export const get12ShenChg = (item: string) => {
	const DataMap: { [key: string]: string[] } = {
		太岁: ['朱雀', '做事情有阻力,不顺还有小人自己要背黑锅。'],
		青龙: ['白虎', '有喜事出现,但最后转成自己受伤害，如失业、受伤、分手、意外等情况'],
		丧门: ['官符', '工作不顺或有纠纷是非口角，最后领导或行政部门出面解决。'],
		六合: ['小耗', '合作合伙的事情失败破财。'],
		官符: ['朱雀', '因工作事业而产生的纠纷官非有小人阻路。'],
		小耗: ['六合', '前凶后吉，合作的事情前期波折多后期顺利。'],
		大耗: ['六合', '前凶后吉，合作的事情前期波折多后期顺利。'],
		朱雀: ['贵神', '会遇到纠纷口解是非,有贵人出现帮忙解决。'],
		白虎: ['青龙', '出现纠纷或人争斗打斗事件，最后得到贵人化解。'],
		贵神: ['丧门', '找人帮助自己结果没帮还害了自己，甚至还有纠纷与官司。'],
		吊客: ['官符', '会遇到纠纷困扰的事情,最后领导或行政部门出面解决。'],
		病符: ['无病', '疾病有了好转或康复。'],

	};
	return DataMap[item];
}





