//通过日干得到五行十神

export const TianGanToShiShen = (DayganWuXing: string, wuXing: string): string => {
	const wuxinglist = ['木', '火', '土', '金', '水']
	const index = wuxinglist.indexOf(wuXing)
	return wuxingToShishenList[DayganWuXing][index]

};


//根据地支得到月份 
export const getMonthByDiZhi = (item: string | string[]) => {

	let refitem: string = '';

	if (Array.isArray(item)) {
		item.forEach(i => refitem += MonthList[dizhiList.indexOf(i)] + ',')
	}
	else {
		refitem = MonthList[dizhiList.indexOf(item)]
	}

	return refitem
}


