// 正月蛇，洞中休，
// 二月老鼠饿昏头，
// 三月老牛遍地走，
// 四月猴子满山溜。6
// 五月兔 4，六月狗 5，
// 七猪 八马 九羊头，
// 十月虎，潢山吼，
// 十一鸡 10，架上栖，
// 十二 老龙海底游。


// 正鸡二兔三羊青，
// 四蛇五马六月龙。
// 七猴八虎九月鼠，
// 十月老牛也有功。
// 十一月猪灰堆卧，
// 腊月狗会把财门。

//  苏国圣：每个生肖均有一个月为其愁月,如生肖为马 的人生于八月即生于愁月，这种人生来愁，无事也生愁，自寻烦恼，自己跟自己过不去，愁事多，压抑悲观。
export const getChouMonth = (item: string) => {
	// 数组格式[愁月，喜月，地支愁月，地支喜月]
	const DataMap: { [key: string]: string[] } = {
		"子": ["二", "九", "卯", "戌"],
		"丑": ["三", "十", "辰", "亥"],
		"寅": ["十", "八", "戌", "酉"],
		"卯": ["五", "二", "午", "卯"],
		"辰": ["十二", "六", "丑", "未"],
		"巳": ["一", "四", "寅", "巳"],
		"午": ["八", "五", "酉", "午"],
		"未": ["九", "三", "戌", "辰"],
		"申": ["四", "七", "巳", "申"],
		"酉": ["十一", "一", "子", "寅"],
		"戌": ["六", "腊", "未", "丑"],
		"亥": ["七", "冬", "申", "子"],
	}
	return DataMap[item];
};





