//天干是否相合 如果相合返回合成的五行，否则返回空字符串  
export const isTianGanHe = (str1: string, str2: string): boolean => {
	const RelaArray = ["甲己合土", "乙庚合金", "丙辛合水", "丁壬合木", "戊癸合火"];
	// 寻找匹配的合化关系，并获取最后一个字符
	return (RelaArray.includes(str1 + str2) || RelaArray.includes(str2 + str1));
};

//天干是否相合 如果相合返回合成的五行，否则返回空字符串  
export const getTianGanHeWu = (str1: string, str2: string): string => {
	const RelaArray = ["甲己合土", "乙庚合金", "丙辛合水", "丁壬合木", "戊癸合火"];
	// 寻找匹配的合化关系，并获取最后一个字符
	let lastChar = ''
	for (const rela of RelaArray) {
		if (rela.startsWith(str1 + str2) || rela.startsWith(str2 + str1)) {
			// 返回匹配元素的最后一个字符
			lastChar = rela[rela.length - 1];
		}
	}
	return lastChar

};

// TagsTmpData
//地支是否相六合  heruflag 合入标志
export const isDiZhiLiuHe = (str1: string, str2: string, heruFlag?: boolean): boolean => {
	const RelaArray = ["午未", "子丑", "寅亥", "卯戌", "辰酉", '巳申'];
	const RelaHeRuArray = ["子丑", "亥寅", "卯戌"];

	if (heruFlag) {
		// 子丑合：子水与丑土相合，可以转化为土的属性。寅亥合：寅木与亥水相合，可以转化为木的属性。卯戌合：卯木与戌土相合，可以转化为火的属性。
		return (RelaHeRuArray.includes(str1 + str2)); //单方合入才成
	}
	else {
		return (RelaArray.includes(str1 + str2) || RelaArray.includes(str2 + str1));
	}



};

