//地支是否相绝 盲派中用到 

// 寅酉绝：也称为金绝，通常指在文道、车马财方面的不利，表示文书隐匿藏私，道路伤灾，筋骨寸断等情况。

// 卯申绝：也称为木绝，主要关联在车马财、道路方面，可能意味着车辆道路的灾殃，财帛遗散，刀枪伤损等。

// 子巳绝：也称为水绝，主要关系到妇女、情义方面，可能涉及到情感变化、分离等情形。

// 午亥绝：也称为火绝，主要关系到口舌、争执方面，可能涉及到文书斗讼、取索争执等。

// 子巳情谊断，寅酉穿血衣，卯申路途死，午亥生闷气。缘分短。   
// 子巳、午亥、卯申、寅酉。命中有四绝为凶象，大运相绝也不吉。卯申相绝
// 如果木火比较少而金水比较多，就比木火多而金水少的人更容易抑郁。


