// 根据贵人能量数值返回对应的标签
export const getEnergyLabel = (energy: number): string => {
	if (energy <= 0) return '';

	if (energy >= 300) {
		return '极强';
	}
	if (energy >= 250) {
		return '超强';
	}
	if (energy >= 200) {
		return '强烈';
	}
	if (energy >= 150) {
		return '很强';
	}
	if (energy >= 100) {
		return '较强';
	}
	if (energy >= 50) {
		return '一般';
	}
	if (energy > 0) {
		return '较弱';
	}

	return '';
}



// 优化后的能量值分级扁平化色块（低端颜色灰色系）
export const getEnergyColor = (energy: number): string => {
	if (energy >= 300) {
		// 极强 — 深红
		return '#B71C1C';
	} else if (energy >= 250) {
		// 超强 — 红
		return '#D32F2F';
	} else if (energy >= 200) {
		// 强烈 — 橙
		return '#F57C00';
	} else if (energy >= 150) {
		// 很强 — 琥珀
		return '#FBC02D';
	} else if (energy >= 100) {
		// 较强 — 绿色
		return '#388E3C';
	} else if (energy >= 50) {
		// 一般 — 中灰
		return '#757575';
	} else if (energy > 0) {
		// 低能量 — 浅灰
		return '#BDBDBD';
	} else {
		// 无能量 — 灰白
		return '#E0E0E0';
	}
}


