//  判断地支是不是相冲  
export const getDiZhiChong = (ganzhi1: string, ganzhi2: string): boolean => {

	let refitem = false;
	const ZhichongArray = ["子午", "丑未", "寅申", "卯酉", "辰戌", "巳亥"];

	// 优化地支相冲的判断，提取为单独的函数以提高可读性
	const isDiZhiChong = (zhi1: string, zhi2: string): boolean => {
		return (ZhichongArray.includes(zhi1 + zhi2) || ZhichongArray.includes(zhi2 + zhi1));
	};

	const dizhiChongFlag = isDiZhiChong(ganzhi1[ganzhi1.length - 1], ganzhi2[ganzhi2.length - 1]);

	if (dizhiChongFlag) {
		refitem = true;
	}

	return refitem;
}


// 根据阴历月份得到阳历的起止日期 

export const getSolarMonthDate = (year: number, lunarMonth: number) => {

	// 初始化一个阴历对象
	const LuncarMonth = LunarMonth.fromYm(year, lunarMonth);

	let dayNum = 30;

	if (LuncarMonth) {
		dayNum = LuncarMonth.getDayCount()
	}

	const lunarLastDay = Lunar.fromYmd(year, lunarMonth, dayNum)
	const lunarStarDay = Lunar.fromYmd(year, lunarMonth, 1)

	return {
		start: lunarStarDay.getSolar(),
		end: lunarLastDay.getSolar(),
	};
}


