// sex 1 男 0 女
export const getThingByZeroByWuxing = (item: string, sex?: number): string => {
	const baseMap: { [key: string]: string } = {
		"官杀": "常感职场受限，喜自由不愿受管；生性散漫，INDEX_INSERT_HERE。",
		"食伤": "多沉默寡言，不善交际；情绪易内敛，需防积郁。",
		"比劫": "生性孤僻，独来独往；同辈缘浅，乏人助力，常孤军奋战。",
		"财才": "与父缘薄，少得荫庇；不重金钱，INDEX_INSERT_HERE不爱理财。",
		"印枭": "母缘浅薄，少得呵护；乏人提携，居无定所，需自力更生。"
	};

	let content = baseMap[item] || "";

	if (item === "官杀") {
		if (sex === 0) content = content.replace("INDEX_INSERT_HERE", "夫缘淡薄，");
		else if (sex === 1) content = content.replace("INDEX_INSERT_HERE", "子嗣缘浅，");
		else content = content.replace("INDEX_INSERT_HERE", "夫缘/子缘淡薄，");
	} else if (item === "财才") {
		if (sex === 1) content = content.replace("INDEX_INSERT_HERE", "妻缘亦浅，");
		else if (sex === 0) content = content.replace("INDEX_INSERT_HERE", ""); // 女命不提
		else content = content.replace("INDEX_INSERT_HERE", "妻缘亦浅，"); // 默认保留
	}

	return content;
}

