// 得到生消的年份 
// 定义十二生肖的类型

// 定义一个映射对象，存储每个生肖的起始年
const zodiacStartYears = {
	鼠: 1924,
	牛: 1925,
	虎: 1926,
	兔: 1927,
	龙: 1928,
	蛇: 1929,
	马: 1930,
	羊: 1931,
	猴: 1932,
	鸡: 1933,
	狗: 1934,
	猪: 1935,
};

// 定义一个方法，接收生肖，返回对应的年份数组

export const getYearsForZodiac = (zodiac: string, nearYearFlag?: Boolean): number[] => {
	const startYear = zodiacStartYears[zodiac];
	// 创建一个数组，存储所有与该生肖对应的年份
	let years: number[] = [];
	for (let year = startYear; year <= 2099; year += 12) {
		years.push(year);
	}

	if (nearYearFlag) {
		let currentYear = new Date().getFullYear();
		return years.filter(year => year > currentYear - 18 && year <= currentYear);
	}
	else {
		return years;
	}

}

