		己: '脾、胰、肌肉、食道、腹、眼',
		庚: '大肠、 骨头',
		辛: '肺、牙齿、咽喉、股骨、胸腔',
		壬: '膀胱、泌尿、血管、',
		癸: '肾、生殖、内分泌、耳朵、大脑、骨髓',
		子: '肾、膀胱',
		丑: '脾胃（表现为消化不好、气虚、乏力)',
		寅: '肝胆 (表现为乏力、食欲不振、肝炎，胆囊炎，肝肿大、牙龈出血)',
		卯: '肝胆 (表现为乏力、食欲不振、肝炎，胆囊炎，肝肿大、牙龈出血)',
		辰: '脾 (表现为消化不好、气虚、乏力)',
		巳: '心血管 (表现为贫血、心脏病、高血压)',
		午: '心血管 (表现为贫血、心脏病、高血压)',
		未: '脾胃 (表现为消化不好、气虚、乏力)',
		申: '肺 (表现为胸闷、气短、咳嗽咳痰)',
