// 定义判断五行关系的方法
//后者与前者的关系，这个有点不同，要注意 
//如果看年干对日干的关系  ， 则日干放前面，年干放后面  
export const getWuXingRelation = (wuXing1: string, wuXing2: string): string => {
	if (!wuXing[wuXing1] || !wuXing[wuXing2]) return '无';
	if (wuXing1 === wuXing2) return '同';
	if (wuXing[wuXing1].生 === wuXing2) return '生';
	if (wuXing[wuXing1].克 === wuXing2) return '克';
	if (wuXing[wuXing2].克 === wuXing1) return '反克';
	if (wuXing[wuXing2].生 === wuXing1) return '反生';
	return '无';
};


