// 得到八字中字符的数量大于等于3次的 
export const getEightChar3Times = (str: string, gz?: string): string[] => {
	const charMap = new Map<string, number>();

	// 遍历字符串，统计每个非空格字符的出现次数
	for (let char of str) {
		if (char.trim() !== '') {
			charMap.set(char, (charMap.get(char) || 0) + 1);
		}
	}

	// 找出出现次数大于等于3的字符
	const charsAppearingThreeOrMoreTimes = [];
	for (let [char, count] of charMap) {
		if (count >= 3) {

			if (gz === 'gan') {
				if (tianganList.includes(char)) {
					charsAppearingThreeOrMoreTimes.push(char);
				}

			}
			else if (gz === 'zhi') {
				if (dizhiList.includes(char)) {
					charsAppearingThreeOrMoreTimes.push(char);
				}

			}
			else {
				charsAppearingThreeOrMoreTimes.push(char);
			}
		}
	}


	return charsAppearingThreeOrMoreTimes;
}

