//根据身强身弱和日主五行来判断喜好是什么 
// 扶抑：旺则泄之，弱则助之，有扶有抑，到达中和。
// 病药：用神选定，又被克害受伤时，伤用神者即是病，必要病得去除，才可反浊为清，有病有药是上等八字，有病无药，一生难得显贵。
// 调侯：五行中和，气侯不得适中，仍无生机不能奋发，尤其是一些金寒水冷、火旺土燥之命，往往以浊而不清来看，得一调侯用神，使命局寒热适中，五行方可流通生化有情。
// 通关：命局只有两种五行，如木土各半，见火通关，金火均衡，见土通关，当两种五行形成互不相让之势，取中间能流通转化的五行通关，使命局的克战变为生助，化敌为友，生生不息。
// 从格：当五行之力旺极无制或衰极无救时，多以物极必反来论，其中有从强、从旺、从弱、从财、从官等。



export const getConfigAttr = (label: string, type: string) => {

	let value: string = '';

	switch (type) {
		case "color":
			// 优先在 TIANGAN.colorsList 中查找
			value = TIANGAN.colorsList[TIANGAN.names.indexOf(label)];
			// 如果在 TIANGAN.colorsList 中未找到，再到 DIZHI.colorsList 中查找
			if (value === undefined) {
				value = DIZHI.colorsList[DIZHI.names.indexOf(label)];
			}
			// 如果在阴是中查找
			if (value === undefined) {
				value = YINYANG.colorsList[YINYANG.names.indexOf(label)];
			}
			break;


		case "yinyangcolor":
			// 优先在 TIANGAN.colorsList 中查找
			value = TIANGAN.yinYangColor[TIANGAN.names.indexOf(label)];
			// 如果在 TIANGAN.colorsList 中未找到，再到 DIZHI.colorsList 中查找
			if (value === undefined) {
				value = DIZHI.yinYangColor[DIZHI.names.indexOf(label)];
			}
			break;
		case "type":
			// 优先在 TIANGAN.colorsList 中查找所属五行
			value = TIANGAN.typesList[TIANGAN.names.indexOf(label)];
			// 如果在 TIANGAN.colorsList 中未找到，再到 DIZHI.colorsList 中查找
			if (value === undefined) {
				value = DIZHI.typesList[DIZHI.names.indexOf(label)];
			}
			break;
		case "guyinyangtype":
			// 优先在 TIANGAN.colorsList 中查找孤阴阳 金水为阴 木火为阳 
			value = TIANGAN.yinYangList2[TIANGAN.names.indexOf(label)];
			// 如果在 TIANGAN.colorsList 中未找到，再到 DIZHI.colorsList 中查找
			if (value === undefined) {
				value = DIZHI.yinYangList2[DIZHI.names.indexOf(label)];
			}
			break;
		case "guyinyangcolor":
			// 优先在 TIANGAN.colorsList 中查找孤阴阳 金水为阴 木火为阳 
			value = TIANGAN.yinYangList2Color[TIANGAN.names.indexOf(label)];
			// 如果在 TIANGAN.colorsList 中未找到，再到 DIZHI.colorsList 中查找
			if (value === undefined) {
				value = DIZHI.yinYangList2Color[DIZHI.names.indexOf(label)];
			}
			break;
		case "wuxing":
			// 优先在 TIANGAN.colorsList 中查找孤阴阳 金水为阴 木火为阳 
			value = ELEMENT.colors[ELEMENT.labels.indexOf(label)];
			// 如果在 TIANGAN.colorsList 中未找到，再到 DIZHI.colorsList 中查找       
			break;
		case "yinyang":
			value = YINYANG.colorsList[YINYANG.names.indexOf(label)];
			break;

	}

	return value;
}


//得到五行的数量统计 
//输入八字的字符串，字符串长度不限数量
export const countElements = (eightCharStr: string[]): {
	[x: string]: any; 木: number, 火: number, 土: number, 金: number, 水: number
} => {
	// 将八字字符串分割为字符数组
	const dateArray = eightCharStr;


	// 用于存储每个五行属性的数量
	const elementCounts = { 木: 0, 火: 0, 土: 0, 金: 0, 水: 0 };
	// 遍历字符数组
	for (const char of dateArray) {
		// 根据字符判断五行属性并增加对应属性的数量
		switch (char) {
			case '甲':
			case '乙':
			case '寅':
			case '卯':
				elementCounts.木++;
				break;
			case '丙':
			case '丁':
			case '巳':
			case '午':
				elementCounts.火++;
				break;
			case '戊':
			case '己':
			case '辰':
			case '未':
			case '戌':
			case '丑':
				elementCounts.土++;
				break;
			case '庚':
			case '辛':
			case '申':
			case '酉':
				elementCounts.金++;
				break;
			case '壬':
			case '癸':
			case '子':
			case '亥':
				elementCounts.水++;
				break;
		}
	}
	return elementCounts;
}



// 输入八字的字符串，字符串长度不限数量
// 其中天干甲，丙，戊，庚，壬为阳，乙，丁，己，辛，癸为阴，

// 地支子，辰，巳，午，戌，亥，由于地支与藏干阴阳不一致，
// 阴中有阳，阳中有阴，故而属于不阴不阳的两面派（如同太监或人妖),
// 而地支中只有 寅，申           为纯阳（地支与藏干皆为阳），
// 地支       丑，卯，未，酉为阴，藏干也全为阴，故为纯阴。


export const countElementsYinYang = (eightCharStr: string[]): { 阴: number, 阳: number, 杂: number } => {
	// 将八字字符串分割为字符数组
	const dateArray = eightCharStr;
	// 用于存储每个五行属性的数量
	const elementCounts = { 阴: 0, 阳: 0, 杂: 0 };
	// 遍历字符数组
	for (const char of dateArray) {
		// 根据字符判断五行属性并增加对应属性的数量
		switch (char) {
			//甲、丙、戊、庚、壬 ---  子、寅、辰、午、申、戌为阳，
			case '甲':
			case '丙':
			case '戊':
			case '庚':
			case '壬':
			case '寅':
			case '申':
				elementCounts.阳++;
				break;
			//乙、丁、己、辛、辛 癸  -- 丑  卯、巳、未、酉、亥为阴
			case '乙':
			case '丁':
			case '己':
			case '辛':
			case '癸':
			case '丑':
			case '卯':
			case '未':
			case '酉':
				elementCounts.阴++;
				break;
			case '子':
				elementCounts.阳++;
				elementCounts.杂++;
				break;
			case '辰':
				elementCounts.阳++;
				elementCounts.杂++;
				break;
			case '巳':
				elementCounts.阴++;
				elementCounts.杂++;
				break;
			case '午':
				elementCounts.阳++;
				elementCounts.杂++;
				break;
			case '戌':
				elementCounts.阳++;
				elementCounts.杂++;
				break;
			case '亥':
				elementCounts.阴++;
				elementCounts.杂++;
				break;
		}
	}
	return elementCounts;
}


//输入八字的字符串，字符串长度不限数量
// 木火为阳，金水为阴，燥土为阳，湿土为阴 
// 甲乙寅卯木、丙丁巳午火、戊戌未土为阳
// 庚辛申酉金、壬癸亥子水、己辰丑土为阴
export const countElementsYinYang2 = (eightCharStr: string[]): { 金水: number, 木火: number } => {
	// 将八字字符串分割为字符数组
	const dateArray = eightCharStr;
	// 用于存储每个五行属性的数量
	const elementCounts = { 金水: 0, 木火: 0 };
	// 遍历字符数组
	for (const char of dateArray) {
		// 根据字符判断五行属性并增加对应属性的数量
		switch (char) {
			//甲、乙：属木； 丙、丁：属火；   
			//  寅、卯：属木；巳、午：属火；辰、戌、丑、未：属土
			//  甲乙寅卯木、丙丁巳午火、戊戌未土为阳
			case '甲':
			case '乙':
			case '丙':
			case '丁':
			case '寅':
			case '卯':
			case '巳':
			case '午':
			case '戊':
			case '戌':
			case '未':
				elementCounts.木火++;
				break;
			// 庚、辛：属金； 壬、癸：属水。，申、酉：属金；亥、子：属水；
			//  庚辛申酉金、壬癸亥子水、己辰丑土为阴
			case '庚':
			case '辛':
			case '壬':
			case '癸':
			case '申':
			case '酉':
			case '亥':
			case '子':
			case '己':
			case '辰':
			case '丑':
				elementCounts.金水++;
				break;
		}
	}
	return elementCounts;
}

//判断后面是前面的什么关系 ，如以日干的关系， 则 第一个参数为日干。 

export const getWuxingShiShen = (wuxing: string, wuxing2: string) => {

	let result: string;

	switch (getWuXingRelation(wuxing, wuxing2)) {
		case '生':
			result = '印枭'
			break;
		case '克':
			result = '官杀'
			break;
		case '同':
			result = '比劫'
			break;
		case '反克':
			result = '财才'
			break;
		case '反生':
			result = '食伤'
			break;
		default:
			result = ''
			break;
	}


	return result;

}


//得出十神的数量来 
export const getShiShenSum = (shiShenArr: string[]) => {
	const baseShiShen: ObjInterface = { 正官: 0, 七杀: 0, 正印: 0, 偏印: 0, 正财: 0, 偏财: 0, 比肩: 0, 劫财: 0, 食神: 0, 伤官: 0 };
	for (let i = 0; i < shiShenArr.length; i++) {
		const shiShen = shiShenArr[i];
		if (baseShiShen[shiShen]) {
			baseShiShen[shiShen]++;
		} else {
			baseShiShen[shiShen] = 1;
		}
	}
	return baseShiShen;
}
//得出十神的数量来 
export const getShiShen = (shiShenArr: string[]) => {
	const baseShiShen: ObjInterface = { 正官: 0, 七杀: 0, 正印: 0, 偏印: 0, 正财: 0, 偏财: 0, 比肩: 0, 劫财: 0, 食神: 0, 伤官: 0 };
	for (let i = 0; i < shiShenArr.length; i++) {
		const shiShen = shiShenArr[i];
		if (baseShiShen[shiShen]) {
			baseShiShen[shiShen]++;
		} else {
			baseShiShen[shiShen] = 1;
		}
	}
	return baseShiShen;
}


//得到五行的统计信息  
export const getEightSumInfo = (eightChar: any) => {

	const eightCharinfo = getEightInfoArary(eightChar)



	return {
		baseinfo: eightCharinfo,
		WuXingSum: countElements(eightCharinfo.eightChar),
		WuXingSumBase: ComputedWuXing(eightChar).wuxingNumObj,
		wuxingIncludeHideSum: countElements(eightCharinfo.eightCharHideArrayNoZhi),
		YinYangSum: countElementsYinYang(eightCharinfo.eightChar),
		YinYangIncludeHideSum: countElementsYinYang(eightCharinfo.eightCharHide),
		YinYangSum2: countElementsYinYang2(eightCharinfo.eightChar),
		YinYangIncludeHideSum2: countElementsYinYang2(eightCharinfo.eightCharHide),
		ShiShenSum: getShiShenSum(eightCharinfo.shiShenArray),
		ShiShenSumBase: ComputedShiShen(eightChar).ShiShen,
		ShiShenWuXingList: ComputedShiShen(eightChar).ShiShenWuXing,
		ShiShenEleList: ComputedShiShen(eightChar).ShiShenEleList
	};

}

//得到八字的基本数组 









//参数是对象，包含了各种方法 

export const getEightInfoArary = (eightChar: any) => {
	//得到不包含或者包含藏干的八字 
	let eightCharHideArray: string[] = [];
	let eightCharHideArrayNoZhi: string[] = [];

	eightCharHideArray = eightCharHideArray.concat(
		eightChar.getYearGan(), eightChar.getYearZhi(), eightChar.getYearHideGan(),
		eightChar.getMonthGan(), eightChar.getMonthZhi(), eightChar.getMonthHideGan(),
		eightChar.getDayGan(), eightChar.getDayZhi(), eightChar.getDayHideGan(),
		eightChar.getTimeGan(), eightChar.getTimeZhi(), eightChar.getTimeHideGan(),
	);
	//计算八字五行的时候，隐藏的支和本命地支是重复的，去掉一个计算的五行才是对的。
	eightCharHideArrayNoZhi = eightCharHideArrayNoZhi.concat(
		eightChar.getYearGan(), eightChar.getYearHideGan(),
		eightChar.getMonthGan(), eightChar.getMonthHideGan(),
		eightChar.getDayGan(), eightChar.getDayHideGan(),
		eightChar.getTimeGan(), eightChar.getTimeHideGan(),
	);
	//得到包含藏干的十神
	let shiShenArray: string[] = [];
	shiShenArray = shiShenArray.concat(eightChar.getYearShiShenGan(), eightChar.getYearShiShenZhi(),
		eightChar.getMonthShiShenGan(), eightChar.getMonthShiShenZhi(), eightChar.getDayShiShenZhi(),
		eightChar.getTimeShiShenGan(), eightChar.getTimeShiShenZhi());
	return {
		eightChar: eightChar.toString().split('').filter((item: string) => item !== ' '),
		eightCharHide: eightCharHideArray,
		eightCharHideArrayNoZhi: eightCharHideArrayNoZhi,
		shiShenArray: shiShenArray,
	};
}

//判断某个天干是否有根   ---有根气通常是指如果日主的天干 五行元素在地支中出现，那么就可以认为日主有根。
//一个人的八字有没有根，就是看地支有没有“比肩”，戊己土不找比肩，要找偏印，而且需为主气，余气不算。善友还可以对照自己的八字：
export const getifExistGen = (eightChar: any, gan: string): boolean => {
	let GenMontherArray: string[] = [];
	let arr = []
	let result: boolean = false;
	GenMontherArray = GenMontherArray.concat(
		eightChar.getYearZhi(),
		eightChar.getMonthZhi(),
		eightChar.getDayZhi(),
		eightChar.getTimeZhi());

	if (gan === '甲' || gan === '乙') {
		arr = ['寅', '卯', '辰', '未', '亥'];
		result = arr.some((item) => GenMontherArray.includes(item));
	}

	if (gan === '丙' || gan === '丁') {
		arr = ['寅', '巳', '午', '未', '戌'];
		result = arr.some((item) => GenMontherArray.includes(item));
	}

	if (gan === '戊' || gan === '己') {
		arr = ['丑', '寅', '辰', '巳', '午', '未', '申', '戌'];
		result = arr.some((item) => GenMontherArray.includes(item));
	}
	if (gan === '庚' || gan === '辛') {
		arr = ['丑', '巳', '申', '酉', '戌'];
		result = arr.some((item) => GenMontherArray.includes(item));
	}

	if (gan === '壬' || gan === '癸') {
		arr = ['子', '丑', '辰', '申', '亥'];
		result = arr.some((item) => GenMontherArray.includes(item));
	}

	return result;
}

// 判断某个地支是不是天干的根  自坐根

export const getifExistSelfGen = (gan: string, zhi: string): boolean => {

	let arr = []
	let result: boolean = false;

	if (gan === '甲' || gan === '乙') {
		arr = ['寅', '卯', '辰', '未', '亥'];
		result = arr.includes(zhi)
	}

	if (gan === '丙' || gan === '丁') {
		arr = ['寅', '巳', '午', '未', '戌'];
		result = arr.includes(zhi)
	}

	if (gan === '戊' || gan === '己') {
		arr = ['丑', '寅', '辰', '巳', '午', '未', '申', '戌'];
		result = arr.includes(zhi)
	}
	if (gan === '庚' || gan === '辛') {
		arr = ['丑', '巳', '申', '酉', '戌'];
		result = arr.includes(zhi)
	}

	if (gan === '壬' || gan === '癸') {
		arr = ['子', '丑', '辰', '申', '亥'];
		result = arr.includes(zhi)
	}

	return result;
}




//得到五行的生囚休死，参数传入月支就可以 
export const getwxrela = (str: string) => {
	let wxguanxi: ObjInterface = {
		'寅卯': ['木旺', '火相', '水休', '金囚', '土死'],
		'巳午': ['火旺', '土相', '木休', '水囚', '金死'],
		'申酉': ['金旺', '水相', '土休', '火囚', '木死'],
		'亥子': ['水旺', '木相', '金休', '土囚', '火死'],
		'辰戌丑未': ['土旺', '金相', '火休', '木囚', '水死']
	};
	// var monthZhi = bazi.getMonthZhi();
	var monthZhi = str
	var wx = [];
	for (var i in wxguanxi) {
		if (i.indexOf(monthZhi) > -1) {
			wx = wxguanxi[i];
			break;
		}
	}

	return wx;
}
