		'午': '【宜】 (午未合 寅午戌合)  【忌】 (子午冲 午午刑 丑午害 卯午破)',
		'未': '【宜】 (午未合 亥卯未合)  【忌】 (丑未冲 丑戌未刑 子未害 未戌破)',
		'申': '【宜】 (巳申合<破> 申子辰合)  【忌】(寅申冲 寅巳申刑 申亥害)',
		'酉': '【宜】 (辰酉合 巳酉丑合) 【忌】 (卯酉冲 酉酉刑 酉戌害 子酉破)',
		'戌': '【宜】 (卯戌合 寅午戌合)  【忌】 (辰戌冲 丑戌未刑 酉戌害 未戌破)',
