//得到三垣 yuan 
export const getSanYuan = (bazi: any) => {
	return '胎元 ' + bazi.getTaiYuan() + '(' + bazi.getTaiYuanNaYin() + ')' + '；命宫 ' + bazi.getMingGong() + '(' + bazi.getMingGongNaYin() + ')' + '；身宫 ' + bazi.getShenGong() + '(' + bazi.getShenGongNaYin() + ')';
}

