export const getShiShenByGan = (dayGan: string, gan: string) => {
	return LunarUtil.SHI_SHEN[dayGan + gan]
}

//随便给一个地支，返回地支隐藏的十神的数组，第一个可以用数组来表示
export const getShiShenByZhi = (dayGan: string, zhi: string) => {
	let dHideGan: string[] = LunarUtil.ZHI_HIDE_GAN[zhi];
	let dShiShenZhi = [];
	if (dHideGan) {
		let size = dHideGan.length;
		for (var x = 0, y = size; x < y; x++) {
			dShiShenZhi.push(LunarUtil.SHI_SHEN[dayGan + dHideGan[x]]);
		}
	}
	return dShiShenZhi;
}

//随便给一个天干或地支，得到天干或地支十神 
export const getShiShenByGanOrZhi = (dayGan: string, Els: string) => {
	if (LunarUtil.GAN.includes(Els)) {
		return [LunarUtil.SHI_SHEN[dayGan + Els]]
	}

	if (LunarUtil.ZHI.includes(Els)) {
		return getShiShenByZhi(dayGan, Els)
	}
}



