//得到干与支的五行， 传递 2个字符 ， 反回两个字符的五行

export const getWuxingByGanZhi = (str: string): string => {
	const Wuxing = LunarUtil.WU_XING_GAN[str.charAt(0)] + LunarUtil.WU_XING_ZHI[str.charAt(1)];
	return Wuxing ? Wuxing : '无';
};

//得到干或支的五行，传递 1个字符 ， 反回五行

//得到干或支的五行，传递 1个字符 ， 反回五行
export const getWuxing = (str: string): string => {
	// 优先从内部定义的 TIANGAN/DIZHI 表中获取，确保逻辑 100% 准确
	const tIndex = TIANGAN.names.indexOf(str);
	if (tIndex !== -1) return TIANGAN.typesList[tIndex];

	const dIndex = DIZHI.names.indexOf(str);
	if (dIndex !== -1) return DIZHI.typesList[dIndex];

	// 备用兜底逻辑
	const Wuxing = LunarUtil.WU_XING_GAN[str] ? LunarUtil.WU_XING_GAN[str] : LunarUtil.WU_XING_ZHI[str];
	return Wuxing ? Wuxing : '无';
};



//得到干支的五行关系以及属性 

export const getMapAttr = (label: string, type = "type") => {
	let el = "水";
	if (LunarUtil.GAN.includes(label)) {
		el = LunarUtil.WU_XING_GAN[label]
	} else if (LunarUtil.ZHI.includes(label)) {
		el = LunarUtil.WU_XING_ZHI[label]
	} else if (ELEMENT.labels.includes(label)) {
		el = label;
	}

	const getElIndex = (el: any) => {
		return ELEMENT.labels.indexOf(el)
	}
	const describeForNameMap: any = {
		label: (el: any) => {
			return el
		},
		color: (el: any) => {
			const index = getElIndex(el)
			return ELEMENT.colors[index]
		},
		type: (el: any) => {
			const index = getElIndex(el)
			return ELEMENT.types[index]
		},
		index: (el: any) => {
			return getElIndex(el)
		}
	}

	return describeForNameMap[type] ? describeForNameMap[type](el) : el;
}

export const timeFormat = (timestamp: number | string | Date, format = "yyyy-mm-dd hh:MM", compat = false) => {
	const date = new Date(timestamp)
	const year = date.getFullYear();
	const month = String(date.getMonth() + 1).padStart(2, '0');
	const day = String(date.getDate()).padStart(2, '0');
	const hours = String(date.getHours()).padStart(2, '0');
	const minutes = String(date.getMinutes()).padStart(2, '0');
	const seconds = String(date.getSeconds()).padStart(2, '0');
	return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
}

export const deleteFirstElement = (list: any) => {
	const newArr = list.slice();
	newArr.shift();
	return newArr;
}

export function firstStringToUpperCase(str: string) {
	return str[0].toUpperCase() + str.charAt(1);
}

