export function getShiShenXing(str: string, type: string) {
	const wuxinglist: ObjInterface =
	{
		"甲": { "比肩": "木", "劫财": "木", "食神": "火", "伤官": "火", "偏财": "土", "正财": "土", "七杀": "金", "正官": "金", "偏印": "水", "正印": "水" },
		"乙": { "比肩": "木", "劫财": "木", "食神": "火", "伤官": "火", "偏财": "土", "正财": "土", "七杀": "金", "正官": "金", "偏印": "水", "正印": "水" },
		"丙": { "比肩": "火", "劫财": "火", "食神": "土", "伤官": "土", "偏财": "金", "正财": "金", "七杀": "水", "正官": "水", "偏印": "木", "正印": "木" },
		"丁": { "比肩": "火", "劫财": "火", "食神": "土", "伤官": "土", "偏财": "金", "正财": "金", "七杀": "水", "正官": "水", "偏印": "木", "正印": "木" },
		"戊": { "比肩": "土", "劫财": "土", "食神": "金", "伤官": "金", "偏财": "水", "正财": "水", "七杀": "木", "正官": "木", "偏印": "火", "正印": "火" },
		"己": { "比肩": "土", "劫财": "土", "食神": "金", "伤官": "金", "偏财": "水", "正财": "水", "七杀": "木", "正官": "木", "偏印": "火", "正印": "火" },
		"庚": { "比肩": "金", "劫财": "金", "食神": "水", "伤官": "水", "偏财": "木", "正财": "木", "七杀": "火", "正官": "火", "偏印": "土", "正印": "土" },
		"辛": { "比肩": "金", "劫财": "金", "食神": "水", "伤官": "水", "偏财": "木", "正财": "木", "七杀": "火", "正官": "火", "偏印": "土", "正印": "土" },
		"壬": { "比肩": "水", "劫财": "水", "食神": "木", "伤官": "木", "偏财": "火", "正财": "火", "七杀": "土", "正官": "土", "偏印": "金", "正印": "金" },
		"癸": { "比肩": "水", "劫财": "水", "食神": "木", "伤官": "木", "偏财": "火", "正财": "火", "七杀": "土", "正官": "土", "偏印": "金", "正印": "金" }
	};




	const eleMap: ObjInterface = {
		"甲": { "比肩": "甲", "劫财": "乙", "食神": "丙", "伤官": "丁", "偏财": "戊", "正财": "己", "七杀": "庚", "正官": "辛", "偏印": "壬", "正印": "癸" },
		"乙": { "比肩": "乙", "劫财": "甲", "食神": "丁", "伤官": "丙", "偏财": "己", "正财": "戊", "七杀": "辛", "正官": "庚", "偏印": "癸", "正印": "壬" },
		"丙": { "比肩": "丙", "劫财": "丁", "食神": "戊", "伤官": "己", "偏财": "庚", "正财": "辛", "七杀": "壬", "正官": "癸", "偏印": "甲", "正印": "乙" },
		"丁": { "比肩": "丁", "劫财": "丙", "食神": "己", "伤官": "戊", "偏财": "辛", "正财": "庚", "七杀": "癸", "正官": "壬", "偏印": "乙", "正印": "甲" },
		"戊": { "比肩": "戊", "劫财": "己", "食神": "庚", "伤官": "辛", "偏财": "壬", "正财": "癸", "七杀": "甲", "正官": "乙", "偏印": "丙", "正印": "丁" },
		"己": { "比肩": "己", "劫财": "戊", "食神": "辛", "伤官": "庚", "偏财": "癸", "正财": "壬", "七杀": "乙", "正官": "甲", "偏印": "丁", "正印": "丙" },
		"庚": { "比肩": "庚", "劫财": "辛", "食神": "壬", "伤官": "癸", "偏财": "甲", "正财": "乙", "七杀": "丙", "正官": "丁", "偏印": "戊", "正印": "己" },
		"辛": { "比肩": "辛", "劫财": "庚", "食神": "癸", "伤官": "壬", "偏财": "乙", "正财": "甲", "七杀": "丁", "正官": "丙", "偏印": "己", "正印": "戊" },
		"壬": { "比肩": "壬", "劫财": "癸", "食神": "甲", "伤官": "乙", "偏财": "丙", "正财": "丁", "七杀": "戊", "正官": "己", "偏印": "庚", "正印": "辛" },
		"癸": { "比肩": "癸", "劫财": "壬", "食神": "乙", "伤官": "甲", "偏财": "丁", "正财": "丙", "七杀": "己", "正官": "戊", "偏印": "辛", "正印": "庚" }
	}
	switch (type) {
		case 'wuxing':
			return wuxinglist[str];
			break;
		case 'ele':
			return eleMap[str];
			break;
		default:
			const keysWithValue = Object.entries(wuxinglist[str])
				.filter(([_, value]) => value === type)
				.map(([key, value]) => key);

			return keysWithValue.toString();
			break;
	}
}


