export const getGanZhiHe = (ganzhi: string): boolean => {

	let ganHeArray = ['甲己', '乙庚', '丙辛', '丁壬', '戊癸', '巳申', '辰酉', '卯戌', '寅亥', '子丑', '午未']


	const isGanHeFlag = (str1: string, str2: string): boolean => {
		return (ganHeArray.includes(str1 + str2) || ganHeArray.includes(str2 + str1));
	};

	return isGanHeFlag(ganzhi[0], ganzhi[1]);
}


