// for (const [key, value] of counts) {
//   console.log(`${key}:$
// {value}`);
// }
export function countArrayElements(arr: any[]): Map<any, number> {
	const elementCounts = new Map<any, number>();

	for (const element of arr) {
		if (elementCounts.has(element)) {
			elementCounts.set(element, elementCounts.get(element)! + 1);
		} else {
			elementCounts.set(element, 1);
		}
	}
	return elementCounts;
}




//输入日干，得到财星列表，返回一个数组，前2个是天干的财星，后2个是地支的财星（甲乙是返回4个,因为地支有4个土)
export function getCaiXing(DayGan: string) {
	const cailist: ObjInterface = {
		'甲': ['己', '戊', '辰', '戌', '丑', '未'],
		'乙': ['戊', '己', '丑', '未', '辰', '戌'],
		'丙': ['辛', '庚', '申', '酉'],
		'丁': ['庚', '辛', '酉', '申'],
		'戊': ['癸', '壬', '子', '亥'],
		'己': ['壬', '癸', '亥', '子'],
		'庚': ['乙', '甲', '卯', '寅'],
		'辛': ['甲', '乙', '寅', '卯'],
		'壬': ['丁', '丙', '午', '巳'],
		'癸': ['丙', '丁', '巳', '午']
	}
	return cailist[DayGan];
}

