export function getShiShang(DayGan: string) {
	const ShiShangelist: ObjInterface = {
		'甲': ['丙', '丁', '巳', '午'], // 甲木生丙火（食神），甲木生丁火（伤官）  
		'乙': ['丁', '丙', '午', '巳'], // 乙木生丁火（食神），乙木生丙火（伤官），但通常乙木以丙火为伤官，丁火为食神（因为乙木为阴，丁火也为阴，同性相生力度小，故为食神）  
		'丙': ['戊', '己', '辰', '戌', '丑', '未'], // 丙火生戊土（食神），丙火生己土（伤官）  
		'丁': ['己', '戊', '丑', '未', '辰', '戌',], // 丁火生己土（食神），丁火生戊土（伤官），但通常丁火以戊土为伤官，己土为食神（因为丁火为阴，己土也为阴）  
		'戊': ['庚', '辛', '申', '酉'], // 戊土生庚金（食神），戊土生辛金（伤官）  
		'己': ['辛', '庚', '酉', '申'], // 己土生辛金（食神），己土生庚金（伤官），但通常己土以庚金为伤官，辛金为食神（因为己土为阴，辛金也为阴）  
		'庚': ['壬', '癸', '亥', '子'], // 庚金生壬水（食神），庚金生癸水（伤官）  
		'辛': ['癸', '壬', '子', '亥'], // 辛金生癸水（食神），辛金生壬水（伤官），但通常辛金以壬水为伤官，癸水为食神（因为辛金为阴，癸水也为阴）  
		'壬': ['甲', '乙', '寅', '卯'], // 壬水生甲木（食神），壬水生乙木（伤官）  
		'癸': ['乙', '甲', '卯', '寅']  // 癸水生乙木（食神），癸水生甲木（伤官），但通常癸水以甲木为伤官，乙木为食神（因为癸水为阴，乙木也为阴）  
	}
	return ShiShangelist[DayGan];
}

// 将两个数组合并成一个不重复的数组 

export function mergeUniqueArray<T>(arr1: T[], arr2: T[]): T[] {
	return [...new Set([...arr1, ...arr2])];
}

// 格式化相对日期
export const formatRelativeDate = (dateStr: string | number): string => {
	if (!dateStr) return '';
	const date = dayjs(dateStr);
	const now = dayjs();
	const diffDays = now.diff(date, 'day');

	if (diffDays === 0) return '今天';
	if (diffDays === 1) return '昨天';
	if (diffDays < 365) return `${diffDays}天前`;
	return date.format('YYYY-MM-DD');
};
